           "nota": "Record com os dados do empréstimo enviados ao front-end.",
           "codigo": "package biblioteca.emprestimo;\n\nimport java.time.LocalDate;\n\n/**\n * Formato dos dados de um empréstimo enviados ao front-end.\n * Um record só guarda dados; o Jackson o converte em JSON com os mesmos nomes dos campos.\n */\npublic record DadosEmprestimo(\n    long id,\n    LivroResumo livro,\n    LeitorResumo leitor,\n    String dataEmprestimo,\n    String dataLimite,\n    long diasDeAtraso,\n    double multa\n) {\n\n    /**\n     * Apenas os dados do livro que a tela precisa.\n     */\n    public record LivroResumo( long id, String titulo, String autor ) {\n    }\n\n    /**\n     * Apenas os dados do leitor que a tela precisa.\n     */\n    public record LeitorResumo( long id, String nome ) {\n    }\n\n    /**\n     * Cria os dados a partir da entidade, calculando atraso e multa para a data de hoje.\n     * LocalDate.toString() gera o texto no formato \"AAAA-MM-DD\".\n     */\n    public static DadosEmprestimo de( Emprestimo emprestimo, LocalDate hoje ) {\n        return new DadosEmprestimo(\n            emprestimo.getId(),\n            new LivroResumo( emprestimo.getLivro().id(), emprestimo.getLivro().titulo(), emprestimo.getLivro().autor() ),\n            new LeitorResumo( emprestimo.getLeitor().id(), emprestimo.getLeitor().nome() ),\n            emprestimo.getDataEmprestimo().toString(),\n            emprestimo.dataLimite().toString(),\n            emprestimo.diasDeAtraso( hoje ),\n            emprestimo.calcularMulta( hoje )\n        );\n    }\n}\n"
