           "codigo": "package biblioteca.livro;\n\nimport java.util.List;\nimport java.util.Optional;\n\n/**\n * Interface: define QUAIS operações existem para os livros, mas não COMO são feitas.\n */\npublic interface RepositorioLivros {\n\n    /**\n     * Retorna todos os livros, em ordem de título.\n     */\n    List< Livro > obterTodos();\n\n    /**\n     * Retorna o livro com o id informado. Optional.empty() indica que ele não existe.\n     */\n    Optional< Livro > obterPorId( long id );\n}\n"
