         "codigo": "-- Dados iniciais para usar a aplicação.\n\nINSERT INTO livro ( titulo, autor, ano ) VALUES\n    ( 'Dom Casmurro', 'Machado de Assis', 1899 ),\n    ( 'O Cortiço', 'Aluísio Azevedo', 1890 ),\n    ( 'Vidas Secas', 'Graciliano Ramos', 1938 ),\n    ( 'Capitães da Areia', 'Jorge Amado', 1937 ),\n    ( 'A Hora da Estrela', 'Clarice Lispector', 1977 ),\n    ( 'Memórias Póstumas de Brás Cubas', 'Machado de Assis', 1881 );\n\nINSERT INTO leitor ( nome, telefone ) VALUES\n    ( 'Ana Souza', '22999990000' ),\n    ( 'Bruno Lima', '22988880000' ),\n    ( 'Carla Mendes', '22977770000' );\n\n-- CURDATE() - INTERVAL 10 DAY: empréstimo feito há 10 dias, portanto com 3 dias de atraso.\nINSERT INTO emprestimo ( livro_id, leitor_id, data_emprestimo ) VALUES\n    ( 1, 1, CURDATE() - INTERVAL 10 DAY ),\n    ( 4, 2, CURDATE() - INTERVAL 2 DAY );\n"
